var flag = true;
var arr1=new Array(""," nghìn"," triệu"," tỷ")
var arr2=new Array("không","mười","hai mươi","ba mươi","bốn mươi","năm mươi","sáu mươi","bảy mươi","tám mươi","chín mươi")
var arr3=new Array("không","một","hai","ba","bốn","năm","sáu","bảy","tám","chín");
var arr4=new Array("mười","mười một","mười hai","mười ba","mười bốn","mười năm","mười sáu","mười bảy","mười tám","mười chín");
var _point="phẩy";
var mangso = ['không','một','hai','ba','bốn','năm','sáu','bảy','tám','chín'];

  function toEnglishCashUSD(inpNumber){
	var roundAmount="";
	var decimalAmount="";
	var node = inpNumber.nextNode();		
	vstrInput = node.childNodes[0].nodeValue;
	var sAmount=vstrInput; 
	var pointPos=sAmount.indexOf(".");	
    
           
        if(pointPos==-1){
            roundAmount=sAmount;
	}else{
		roundAmount=sAmount.substring(0,pointPos);
		decimalAmount=sAmount.substring(pointPos+1,sAmount.length);
	}
           while(decimalAmount!="" && decimalAmount[decimalAmount.length-1]=="0"){
	decimalAmount=decimalAmount.substring(0, decimalAmount.length-1);
        }
           var chuoi=  toEnglishCash(roundAmount);
	
        if(decimalAmount!=""){
        
        var chuoidot= toEnglishCash(decimalAmount);
        if(decimalAmount.length==2  && decimalAmount.substring(0,1)=="0"){
        chuoidot= "không "+chuoidot;
        }else if(decimalAmount.length==3 &&  decimalAmount.substring(0,1)=="0"){
        chuoidot= "không trăm "+chuoidot;
        }else if(decimalAmount.length==4  &&  decimalAmount.substring(0,1)=="0"){
        chuoidot= "không nghìn "+chuoidot;
        }
       chuoi=chuoi+" phẩy " +chuoidot;
        }
		chuoi = chuoi.substring(1,2).toUpperCase()+ chuoi.substring(2);
	return chuoi;
	
}


function toEnglishCash(so){
	so = so.replace(/[^0-9.]/g, '');
     
	 if (so==0) return " không";
        var chuoi = "", hauto = "";
         do {
            ty = so%1000000000;
            so = Math.floor(so/1000000000);
            if (so>0) {
                chuoi = dochangtrieu(ty,true) + hauto + chuoi;
            } else {
                chuoi = dochangtrieu(ty,false) + hauto + chuoi;
            }
            hauto = " tỷ";
        } while (so>0);               
    return chuoi;
}


function dochangtrieu(so,daydu)
    {
        var chuoi = "";
        trieu = Math.floor(so/1000000);
        so = so%1000000;
        if (trieu>0) {
            chuoi = docblock(trieu,daydu) + " triệu";
            daydu = true;
        }
        nghin = Math.floor(so/1000);
        so = so%1000;
        if (nghin>0) {
            chuoi += docblock(nghin,daydu) + " nghìn";
            daydu = true;
        }
        if (so>0) {
            chuoi += docblock(so,daydu);
        }
        return chuoi;
    }

 function dochangchuc(so,daydu)
    {
        var chuoi = "";
        chuc = Math.floor(so/10);
        donvi = so%10;
        if (chuc>1) {
            chuoi = " " + mangso[chuc] + " mươi";
            if (donvi==1) {
                chuoi += " mốt";
            }
        } else if (chuc==1) {
            chuoi = " mười";
            if (donvi==1) {
                chuoi += " một";
            }
        } else if (daydu && donvi>0) {
            chuoi = " lẻ";
        }
        if (donvi==5 && chuc>1) {
            chuoi += " lăm";
        } else if (donvi>1||(donvi==1 && chuc==0)) {
            chuoi += " " + mangso[ donvi ];
        } 
        return chuoi;
    }
	
    function docblock(so,daydu)
    {
        var chuoi = "";
        tram = Math.floor(so/100);
        so = so%100;
        if (daydu || tram>0) {
            chuoi = " " + mangso[tram] + " trăm";
            chuoi += dochangchuc(so,true);
        } else {
            chuoi = dochangchuc(so,false);
        }
        return chuoi;
    }
    
    function docso(so)
    {
        if (so==0) return " không";
        var chuoi = "", hauto = "";
        do {
            ty = so%1000000000;
            so = Math.floor(so/1000000000);
            if (so>0) {
                chuoi = dochangtrieu(ty,true) + hauto + chuoi;
            } else {
                chuoi = dochangtrieu(ty,false) + hauto + chuoi;
            }
            hauto = " tỷ";
        } while (so>0);
        return chuoi;
    } 

